+    offset += L_LBM_SRS_REGISTRATION_REQUEST_INFO_T_HOST_ID;
+    proto_tree_add_item(lbmsrs_details_tree, hf_lbmsrs_protocol_version, tvb, offset, L_LBM_SRS_REGISTRATION_REQUEST_INFO_T_PROTOCOL_VERSION, ENC_BIG_ENDIAN);
